// Package argparse is a small command-line argument parser supporting boolean
// flags, flags with values, positional arguments and generated help.
//
// Accepted syntax:
//
//	--name            boolean flag
//	--name=value      flag with value (also --bool=false)
//	--name value      flag with value
//	-n                short boolean flag
//	-abc              combined short boolean flags
//	-n value, -nvalue short flag with value
//	--                everything after is positional
package argparse

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"text/tabwriter"
	"unicode/utf8"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	long  string
	short rune // 0 if none
	usage string
	kind  string // "bool", "string" or "int"
	def   string // default shown in help, "" if none
	set   func(string) error
}

type arg struct {
	name     string
	usage    string
	required bool
	target   *string
}

// Parser holds flag and positional argument definitions.
type Parser struct {
	name  string
	desc  string
	flags []*flag
	long  map[string]*flag
	short map[rune]*flag
	args  []*arg
	rest  []string
}

// New returns a parser for a program with the given name and description.
func New(name, desc string) *Parser {
	return &Parser{
		name:  name,
		desc:  desc,
		long:  map[string]*flag{},
		short: map[rune]*flag{},
	}
}

func (p *Parser) add(f *flag) {
	if f.long == "" || strings.HasPrefix(f.long, "-") || strings.Contains(f.long, "=") {
		panic(fmt.Sprintf("argparse: invalid flag name %q", f.long))
	}
	if _, ok := p.long[f.long]; ok {
		panic("argparse: flag redefined: --" + f.long)
	}
	p.long[f.long] = f
	if f.short != 0 {
		if _, ok := p.short[f.short]; ok {
			panic("argparse: flag redefined: -" + string(f.short))
		}
		p.short[f.short] = f
	}
	p.flags = append(p.flags, f)
}

// Bool defines a boolean flag. Pass 0 as short for no short form.
func (p *Parser) Bool(long string, short rune, usage string) *bool {
	v := new(bool)
	p.add(&flag{long: long, short: short, usage: usage, kind: "bool", set: func(s string) (err error) {
		*v, err = strconv.ParseBool(s)
		return err
	}})
	return v
}

// String defines a string flag with a default value.
func (p *Parser) String(long string, short rune, def, usage string) *string {
	v := new(string)
	*v = def
	f := &flag{long: long, short: short, usage: usage, kind: "string", set: func(s string) error {
		*v = s
		return nil
	}}
	if def != "" {
		f.def = strconv.Quote(def)
	}
	p.add(f)
	return v
}

// Int defines an integer flag with a default value.
func (p *Parser) Int(long string, short rune, def int, usage string) *int {
	v := new(int)
	*v = def
	f := &flag{long: long, short: short, usage: usage, kind: "int", set: func(s string) (err error) {
		*v, err = strconv.Atoi(s)
		return err
	}}
	if def != 0 {
		f.def = strconv.Itoa(def)
	}
	p.add(f)
	return v
}

// Arg defines the next positional argument. Required arguments must be
// defined before optional ones.
func (p *Parser) Arg(name, usage string, required bool) *string {
	if required && len(p.args) > 0 && !p.args[len(p.args)-1].required {
		panic("argparse: required argument <" + name + "> defined after an optional one")
	}
	v := new(string)
	p.args = append(p.args, &arg{name: name, usage: usage, required: required, target: v})
	return v
}

// Rest returns positional arguments beyond those defined with Arg.
func (p *Parser) Rest() []string { return p.rest }

// Parse parses args, which should not include the program name.
// It returns ErrHelp if help was requested.
func (p *Parser) Parse(args []string) error {
	var pos []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case a == "--":
			pos = append(pos, args[i+1:]...)
			i = len(args)

		case strings.HasPrefix(a, "--"):
			name, val, hasVal := strings.Cut(a[2:], "=")
			f, ok := p.long[name]
			if !ok {
				if name == "help" {
					return ErrHelp
				}
				return fmt.Errorf("unknown flag --%s", name)
			}
			if !hasVal {
				if f.kind == "bool" {
					val = "true"
				} else if i++; i < len(args) {
					val = args[i]
				} else {
					return fmt.Errorf("flag --%s needs a value", name)
				}
			}
			if err := f.set(val); err != nil {
				return fmt.Errorf("invalid value %q for --%s: expected %s", val, name, f.kind)
			}

		case len(a) > 1 && a[0] == '-':
			// Cluster of short flags; the first one taking a value
			// consumes the remainder of the token or the next argument.
			for cluster := a[1:]; cluster != ""; {
				r, size := utf8.DecodeRuneInString(cluster)
				cluster = cluster[size:]
				f, ok := p.short[r]
				if !ok {
					if r == 'h' {
						return ErrHelp
					}
					return fmt.Errorf("unknown flag -%c", r)
				}
				val := "true"
				if f.kind != "bool" {
					if cluster != "" {
						val = strings.TrimPrefix(cluster, "=")
					} else if i++; i < len(args) {
						val = args[i]
					} else {
						return fmt.Errorf("flag -%c needs a value", r)
					}
					cluster = ""
				}
				if err := f.set(val); err != nil {
					return fmt.Errorf("invalid value %q for -%c: expected %s", val, r, f.kind)
				}
			}

		default:
			pos = append(pos, a)
		}
	}

	for i, d := range p.args {
		if i < len(pos) {
			*d.target = pos[i]
		} else if d.required {
			return fmt.Errorf("missing argument <%s>", d.name)
		}
	}
	p.rest = nil
	if len(pos) > len(p.args) {
		p.rest = pos[len(p.args):]
	}
	return nil
}

// MustParse parses os.Args[1:]. On --help it prints usage and exits 0; on
// error it prints the error and usage to stderr and exits 2.
func (p *Parser) MustParse() {
	switch err := p.Parse(os.Args[1:]); {
	case err == ErrHelp:
		p.Usage(os.Stdout)
		os.Exit(0)
	case err != nil:
		fmt.Fprintf(os.Stderr, "%s: %v\n\n", p.name, err)
		p.Usage(os.Stderr)
		os.Exit(2)
	}
}

// Usage writes a help message generated from the definitions to w.
func (p *Parser) Usage(w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [options]", p.name)
	for _, d := range p.args {
		if d.required {
			fmt.Fprintf(w, " <%s>", d.name)
		} else {
			fmt.Fprintf(w, " [%s]", d.name)
		}
	}
	fmt.Fprintln(w)
	if p.desc != "" {
		fmt.Fprintf(w, "\n%s\n", p.desc)
	}

	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	if len(p.args) > 0 {
		fmt.Fprintln(tw, "\nArguments:")
		for _, d := range p.args {
			fmt.Fprintf(tw, "  %s\t%s\n", d.name, d.usage)
		}
	}

	fmt.Fprintln(tw, "\nOptions:")
	row := func(f *flag) {
		left := "      --" + f.long
		if f.short != 0 {
			left = fmt.Sprintf("  -%c, --%s", f.short, f.long)
		}
		if f.kind != "bool" {
			left += " <" + f.kind + ">"
		}
		usage := f.usage
		if f.def != "" {
			usage += " (default " + f.def + ")"
		}
		fmt.Fprintf(tw, "%s\t%s\n", left, usage)
	}
	for _, f := range p.flags {
		row(f)
	}
	if _, ok := p.long["help"]; !ok {
		help := &flag{long: "help", kind: "bool", usage: "show this help"}
		if _, taken := p.short['h']; !taken {
			help.short = 'h'
		}
		row(help)
	}
	tw.Flush()
}

package argparse

import (
	"reflect"
	"strings"
	"testing"
)

type result struct {
	verbose, force bool
	output         string
	count          int
	input, dest    string
	rest           []string
}

func parse(args ...string) (result, error) {
	p := New("prog", "Test program.")
	verbose := p.Bool("verbose", 'v', "verbose output")
	force := p.Bool("force", 'f', "overwrite")
	output := p.String("output", 'o', "out.txt", "output file")
	count := p.Int("count", 'n', 1, "repeat count")
	input := p.Arg("input", "input file", true)
	dest := p.Arg("dest", "destination", false)
	err := p.Parse(args)
	return result{*verbose, *force, *output, *count, *input, *dest, p.Rest()}, err
}

func TestParse(t *testing.T) {
	tests := []struct {
		args []string
		want result
	}{
		{[]string{"in"}, result{output: "out.txt", count: 1, input: "in"}},
		{[]string{"--verbose", "--output", "x", "in"}, result{verbose: true, output: "x", count: 1, input: "in"}},
		{[]string{"--output=x", "--count=3", "in", "d"}, result{output: "x", count: 3, input: "in", dest: "d"}},
		{[]string{"-vf", "-o", "x", "in"}, result{verbose: true, force: true, output: "x", count: 1, input: "in"}},
		{[]string{"-vox", "-n5", "in"}, result{verbose: true, output: "x", count: 5, input: "in"}},
		{[]string{"-n=7", "in"}, result{output: "out.txt", count: 7, input: "in"}},
		{[]string{"--count", "-2", "in"}, result{output: "out.txt", count: -2, input: "in"}},
		{[]string{"--verbose=false", "in"}, result{output: "out.txt", count: 1, input: "in"}},
		{[]string{"--output=", "in"}, result{count: 1, input: "in"}},
		{[]string{"in", "-v", "d", "a", "b"}, result{verbose: true, output: "out.txt", count: 1, input: "in", dest: "d", rest: []string{"a", "b"}}},
		{[]string{"--", "-v", "--x"}, result{output: "out.txt", count: 1, input: "-v", dest: "--x"}},
		{[]string{"-"}, result{output: "out.txt", count: 1, input: "-"}},
	}
	for _, tt := range tests {
		got, err := parse(tt.args...)
		if err != nil {
			t.Errorf("%q: unexpected error: %v", tt.args, err)
		} else if !reflect.DeepEqual(got, tt.want) {
			t.Errorf("%q:\n got %+v\nwant %+v", tt.args, got, tt.want)
		}
	}
}

func TestParseErrors(t *testing.T) {
	tests := []struct {
		args []string
		want string
	}{
		{[]string{}, "missing argument <input>"},
		{[]string{"--nope", "in"}, "unknown flag --nope"},
		{[]string{"-vx", "in"}, "unknown flag -x"},
		{[]string{"in", "--output"}, "flag --output needs a value"},
		{[]string{"in", "-o"}, "flag -o needs a value"},
		{[]string{"--count=abc", "in"}, `invalid value "abc" for --count: expected int`},
		{[]string{"--verbose=maybe", "in"}, `invalid value "maybe" for --verbose: expected bool`},
	}
	for _, tt := range tests {
		if _, err := parse(tt.args...); err == nil || err.Error() != tt.want {
			t.Errorf("%q: got error %v, want %q", tt.args, err, tt.want)
		}
	}
}

func TestHelp(t *testing.T) {
	for _, a := range []string{"-h", "--help", "-vh"} {
		if _, err := parse(a); err != ErrHelp {
			t.Errorf("%s: got %v, want ErrHelp", a, err)
		}
	}
}

func TestUsage(t *testing.T) {
	p := New("prog", "Test program.")
	p.Bool("verbose", 'v', "verbose output")
	p.String("output", 'o', "out.txt", "output file")
	p.Int("count", 0, 0, "repeat count")
	p.Arg("input", "input file", true)
	p.Arg("dest", "destination", false)

	var b strings.Builder
	p.Usage(&b)
	want := `Usage: prog [options] <input> [dest]

Test program.

Arguments:
  input  input file
  dest   destination

Options:
  -v, --verbose          verbose output
  -o, --output <string>  output file (default "out.txt")
      --count <int>      repeat count
  -h, --help             show this help
`
	if b.String() != want {
		t.Errorf("got:\n%s\nwant:\n%s", b.String(), want)
	}
}

